function detect(env, err) {
  if (!env || !env.DB)
    return "binding";
  const msg = String(err?.message ?? err ?? "");
  if (/no such table/i.test(msg))
    return "tables";
  if (/no such column/i.test(msg))
    return "tables";
  return "generic";
}
var esc = (s) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
