function parseColumns(createSql) {
  const m = /\(([\s\S]*)\)\s*$/.exec(createSql.replace(/\s+$/, ""));
  if (!m)
    return [];
  const body = m[1];
  const parts = [];
  let depth = 0;
  let cur = "";
  for (const ch of body) {
    if (ch === "(")
      depth++;
    else if (ch === ")")
      depth--;
    if (ch === "," && depth === 0) {
      parts.push(cur);
      cur = "";
      continue;
    }
    cur += ch;
  }
  parts.push(cur);
  return parts.map((p) => p.trim().split(/\s+/)[0]?.replace(/["'`]/g, "") ?? "").filter((c) => c && !/^(PRIMARY|UNIQUE|CHECK|FOREIGN|CONSTRAINT)$/i.test(c));
}
var TABLES = (() => {
  const map = /* @__PURE__ */ new Map();
  for (const stmt of SCHEMA) {
    const m = /CREATE TABLE IF NOT EXISTS (\w+)/.exec(stmt.sql) ?? /CREATE INDEX IF NOT EXISTS \w+ ON (\w+)/.exec(stmt.sql) ?? /ALTER TABLE (\w+)/.exec(stmt.sql);
    if (!m)
      continue;
    let def = map.get(m[1]);
    if (!def) {
      def = { name: m[1], stmts: [], columns: [] };
      map.set(m[1], def);
    }
    def.stmts.push(stmt);
  }
  for (const def of map.values()) {
    const create = def.stmts.find((s) => /CREATE TABLE IF NOT EXISTS/.test(s.sql));
    if (create)
      def.columns = parseColumns(create.sql);
  }
  return [...map.values()];
})();
