  if (!g)
    return c.json({ ok: false, error: "forbidden" }, c.get("user") ? 403 : 400);
  const { env } = g;
  const name = c.req.param("name");
  if (EXPECTED.has(name))
    return c.json({ ok: false, error: "protected_table" }, 400);
  if (!/^\w+$/.test(name))
    return c.json({ ok: false, error: "bad_name" }, 400);
  try {
    await env.DB.prepare(`DROP TABLE IF EXISTS ${name}`).run();
  } catch (e) {
    return c.json({ ok: false, error: "drop_failed", detail: String(e?.message ?? e).slice(0, 240) }, 500);
  }
