        mx_ok: mxRecords.length > 0,
        mx_cloudflare: cfMx,
        mx_records: mxRecords.slice(0, 6),
        spf_ok: !!spf,
        spf_cloudflare: spfCf,
        spf_record: spf,
        checked_at: now()
